def parse_gt(value):
    gt = value.split(":", 1)[0] if value else "."
    if not gt or "." in gt:
        return None
    alleles = gt.replace("|", "/").split("/")
    if not alleles or not all(a.isdigit() for a in alleles):
        return None
    return tuple(int(a) for a in alleles)


def dosage_for_alt(gt, alt_index):
    if gt is None:
        return None
    return sum(a == alt_index for a in gt)


